import React, { useState } from 'react';
import { fmtPhone } from '../utils/helpers';
import { Icons } from '../components/ui/Icons';

export function RegisterModal({ onClose, onLogin, toast }) {
    const [f, setF] = useState({ phone: "", last: "", first: "", pass: "", pass2: "", agree: false });
    const [loading, setLoading] = useState(false);

    const upd = k => e => setF(p => ({ ...p, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value }));

    const submit = async () => {
        if (f.pass !== f.pass2) {
            toast.err("Пароли не совпадают");
            return;
        }
        if (f.pass.length < 6) {
            toast.err("Пароль минимум 6 символов");
            return;
        }
        if (!f.agree) {
            toast.err("Примите условия использования");
            return;
        }
        setLoading(true);
        await new Promise(r => setTimeout(r, 1100));
        setLoading(false);
        toast.ok("Регистрация прошла успешно! 🎉");
        onLogin();
    };

    return (
        <div className="modal-ov" onClick={e => e.target === e.currentTarget && onClose()}>
            <div className="modal">
                <div className="m-hdr">
                    <div className="m-ttl">
                        <span className="ico">◇</span>Регистрация
                    </div>
                    <button className="m-x" onClick={onClose}>
                        ✕
                    </button>
                </div>
                <div className="m-body">
                    <div className="fg">
                        <div className="fl">
                            <Icons.Phone />
                            Телефон
                        </div>
                        <input
                            className="fi"
                            type="tel"
                            placeholder="+7 (___) ___-__-__"
                            value={f.phone}
                            onChange={e => setF(p => ({ ...p, phone: fmtPhone(e.target.value) }))}
                        />
                    </div>
                    <div className="fi-row">
                        <div className="fg">
                            <div className="fl">Фамилия</div>
                            <input className="fi" placeholder="Фамилия" value={f.last} onChange={upd("last")} />
                        </div>
                        <div className="fg">
                            <div className="fl">Имя</div>
                            <input className="fi" placeholder="Имя" value={f.first} onChange={upd("first")} />
                        </div>
                    </div>
                    <div className="fg" style={{ marginTop: 20 }}>
                        <div className="fl">
                            <Icons.Lock />
                            Пароль
                        </div>
                        <input
                            className="fi"
                            type="password"
                            placeholder="Минимум 6 символов"
                            value={f.pass}
                            onChange={upd("pass")}
                        />
                    </div>
                    <div className="fg">
                        <div className="fl">
                            <Icons.Lock />
                            Подтверждение
                        </div>
                        <input
                            className="fi"
                            type="password"
                            placeholder="Повторите пароль"
                            value={f.pass2}
                            onChange={upd("pass2")}
                        />
                    </div>
                    <div className="f-check">
                        <input type="checkbox" id="ag" checked={f.agree} onChange={upd("agree")} />
                        <label htmlFor="ag">
                            Я принимаю <a href="#">условия использования</a> и <a href="#">политику конфиденциальности</a>
                        </label>
                    </div>
                    <button className="submit" onClick={submit} disabled={loading || !f.phone || !f.first || !f.pass}>
                        {loading ? "Создаём аккаунт..." : "Зарегистрироваться"}
                    </button>
                </div>
                <div className="m-ftr">
                    <p>
                        Уже есть аккаунт? <a onClick={onLogin}>Войти</a>
                    </p>
                </div>
            </div>
        </div>
    );
}
